        foreach(var (name,size) in new[]{("AR_INVOICE_ID",128),("PAYMENT_NUMBER",128),("PAYMENT_METHOD",32),("CHECK_NUMBER",128),("OWNER_TENANT_ID",128),("OWNER_COMPANY_BA_ID",128),("BOOK_ID",128),("FIELD_ID",128),("CURRENCY_CODE",16),("PAYER_BA_ID",128),("EXTERNAL_REFERENCE",256),("EVIDENCE_REFERENCE",2000),("STATUS",32),("SOURCE_REVISION",64),("PREPARATION_WORKFLOW_JSON",CompanySalesPaymentProof.MaximumLength)}){var fields=schema?.Fields?.Where(field=>field.FieldName==name).ToArray();if(fields is not {Length:1} || fields[0].Fieldtype!=typeof(string).FullName || Math.Max(fields[0].Size,fields[0].Size1)<size)throw new InvalidOperationException("The complete bounded native payment metadata/receipt is unconfirmed.");}
